def countWordSquares(words):
    L = len(words[0])
    by_prefix = {}
    for w in words:
        for k in range(L):
            by_prefix.setdefault(tuple(w[:k]), []).append(w)
    rows = []

    def go():
        k = len(rows)
        if k == L:
            return 1
        prefix = tuple(rows[i][k] for i in range(k))
        total = 0
        for w in by_prefix.get(prefix, ()):
            rows.append(w)
            total += go()
            rows.pop()
        return total

    return go()
